#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>

static long long safe_abs_ll(long long x) {
    if (x < 0) {
        if (x == LLONG_MIN) {
            return LLONG_MIN; // caller will treat as overflow
        }
        return -x;
    }
    return x;
}

static long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    char *endptr;
    errno = 0;
    long long a = strtoll(argv[1], &endptr, 10);
    if (*endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }

    errno = 0;
    long long b = strtoll(argv[2], &endptr, 10);
    if (*endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }

    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    long long abs_a = safe_abs_ll(a);
    long long abs_b = safe_abs_ll(b);

    if (abs_a > 1000000LL || abs_b > 1000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    long long g = gcd_ll(abs_a, abs_b);
    long long l = (g == 0) ? 0 : (abs_a / g) * abs_b;
    printf("gcd=%lld lcm=%lld\n", g, l);
    return 0;
}
